package com.luminor.tavernquest.feature.splash
import androidx.compose.foundation.layout.*;import androidx.compose.material3.Text;import androidx.compose.runtime.*;import androidx.compose.ui.*;import androidx.compose.ui.unit.sp;import androidx.hilt.navigation.compose.hiltViewModel;import com.luminor.tavernquest.core.designsystem.components.MedievalLoading;import com.luminor.tavernquest.navigation.AppRoute
@Composable fun SplashScreen(vm:SplashViewModel=hiltViewModel(),onReady:(String)->Unit){val done by vm.completed.collectAsState();LaunchedEffect(done){done?.let{onReady(if(it)AppRoute.Home else AppRoute.Welcome)}};Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Column(horizontalAlignment=Alignment.CenterHorizontally){Text("TavernQuest",fontSize=34.sp);MedievalLoading()}}}
